\begin{exam}
任意の$p\in[1,+\mgn)$に対して$p$-ノルムと$\mgn$-ノルムは同値となる。実際
\[
|x_i|\le\mrn{x}
\]
より
\[
\prn{x}\le \left(\sum_{i=1}^N\mrn{x}^p\right)^{\frac{1}{p}}\le \sqrt[p]{N}\mrn{x}
\]
であり、また明らかに
\[
|x_i|\le\left(\sum_{i=1}^N|x_{i}|^p\right)^{\frac{1}{p}}=\prn{x}
\]
なので
\[
\mrn{x}\le\prn{x}\le \sqrt[p]{N}\mrn{x}
\]となり、同値であることがわかる。\\ 
ノルムの同値性は同値関係になるので$p$-ノルム同士は同値であり、更に同じ同値類に$\mgn$-ノルムが入っている。特に$2$-ノルムと$\mgn$-ノルムは同値なので$\mgn$-ノルムと$2$-ノルムが定める$\rr^N$の位相は同じ位相である。つまり位相空間としての$(\rr^N,\mrn{\bullet})$は通常のユークリッド位相空間である。
\end{exam}

\begin{thm}\label{aa}
位相空間$X$について以下は同値である。
\begin{enumerate}
\item $X$は可算コンパクト
\item $X$の可算部分集合$A$に完全集積点が存在する。
\item $X$の無限部分集合$A$について点$a\in X$が存在して$a$の任意の近傍$N$について
\[
\card(A\cap N)\ge \aleph_0
\]
を充たす。
\end{enumerate}
\end{thm}

\begin{df}
二つの集合$A, B$の直積
$A\times B$の部分集合$S$に対して，
\[
\myprojb{S}=\{a\in A\mid \exists b\in B\ (a, b)\in S\}
\]
\[
\myproja{S}=\{b\in B\mid \exists a\in A\ (a, b)\in S\}
\]
と定義する．
つまり，
$\myprojb{S}$は第一成分への射影で，
$\myproja{S}$は第二成分への射影である．
\begin{rmk}
とんでもないノーテーションである．
\end{rmk}
また，$a\in A$と$b\in B$に対して

\[
\mysliceb{S}{b}=\{a\in A\mid (a,b)\in S\}
\]
\[
\myslicea{S}{a}=\{b\in B\mid (a, b)\in S\}
\]
と定義する．つまり，スライスのことである．
\end{df}
